def largest_smallest_integers(lst):
    if not lst:
        return (None, None)

    # First, separate negative and positive integers
    negatives = [num for num in lst if num < 0]
    positives = [num for num in lst if num >= 0]

    # Determine the largest and smallest values
    largest = None
    smallest = None
    if negatives:
        largest = max(negatives)
    if positives:
        smallest = min(positives)

    return (largest, smallest)
```

