import sys

def largest_smallest_integers(lst):
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''
    if not lst:
        return (None, None)

    # Filter out negative numbers and non-integer values
    negative_numbers = [num for num in lst if isinstance(num, int) and num < 0]
    positive_numbers = [num for num in lst if isinstance(num, int)]

    if len(negative_numbers) > 0:
        # Return the largest negative number
        a = max(negative_numbers)
        return (a, None)
    elif len(positive_numbers) > 0:
        # Return the smallest positive number
        b = min(positive_numbers)
        return (None, b)
    else:
        # Return None if there are no negative or positive numbers
        return (None, None)
```

