def valid_date(date):
    """Check if the given date string is valid."""
    try:
        # Accept the date string in the correct format
        date = datetime.strptime(date, '%m-%d-%Y').date()

        # Check if the date is in the correct format
        if datetime.strptime(date, '%m-%d-%Y').month < 1 or datetime.strptime(date, '%m-%d-%Y').month > 12:
            return False

        # Check if the data is valid month
        if datetime.strptime(date, '%m-%d-%Y').month not in [1, 3, 5, 7, 8, 10, 12]:
            return False

        # Check if the day format is correct
        if datetime.strptime(date, '%m-%d-%Y').day < 1 or datetime.strptime(date, '%m-%d-%Y').day > 30:
            return False

        # Check if the year is valid
        if int(date[:4]) < 1900 or int(date[:4]) > 2021:
            return False

        return True
    except ValueError:
        return False
```

