def tri(n):
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]
    else:
        a, b, c = 1, 3, 2
        for i in range(3, n + 1):
            if i % 2 == 0:
                c = a + b + tri(i - 1)
            else:
                c = a + b + tri(i - 2)
            a, b, c = b, c, c + a
        return [a] + [c] * (n - 1)
