def split_words(txt):
    # Check if the string contains only whitespace
    if txt.isspace():
        return [txt]

    # If there are no commas in the string, return the count of lower-case letters with odd alphabet order
    if ',' not in txt:
        return [ord(x) - ord('a') for x in txt.lower() if ord(x) - ord('a') % 2 == 0]
    else:
        return [ord(x) - ord('a') for x in txt.split(',')]
```

