def search(lst):
    if not lst:
        return -1

    freq_dict = {}
    for num in lst:
        freq_dict[num] = freq_dict.get(num, 0) + 1

    max_value = -1
    for num, freq in freq_dict.items():
        if freq >= num and freq > max_value:
            max_value = freq

    return max_value


