from typing import List

def monotonic(l: List[int]) -> List[bool]:
    """Return True if elements in the list are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    ascending, descending = l[:-1], l[1:]
    for size in range(len(l) - 1):
        if l[size] > l[size + 1]:
            return False
        if l[size] < l[size + 1]:
            if len(ascending) > 0:
                if l[size] <= ascending[0]:
                    return False
            if len(descending) > 0:
                if l[size] >= descending[0]:
                    return True
        if get_sign(l[size]) * l[size] >= 0:
            return False
    if len(descending) > 0:
        return True
    return False

def get_sign(val: int) -> int:
    """Return sign of the number should arguments change direction sign"""
    sign = -1 if val > 0 else 1
    for i in range(2, abs(val) + 1):
        if not get_rev_sign(i-1):
            break
    return sign

def get_rev_sign(sz: int) -> bool: 
    """Return sign flip if array changes direction after first negate."""
    return not get_sign(-sz)

