def split_words(txt):
    def count_odd_spaced_letters(s):
        count_odd = 0
        for char in s:
            if ord(char) <= 100 and ord(char) >= 33:
                count_odd += 1
        if count_odd % 2 == 0:
            return len(s) - count_odd
        else:
            return len(s)

    # If no whitespace is found, split on commas
    if ' ' not in txt:
        return txt.split(',')
    else:
        # Return the count of lowercase odd-spaced letters
        return count_odd_spaced_letters(txt) // 2

