def is_nested(string):
    def is_nested_helper(substring):
        stack = []
        for char in substring:
            if char == '[':
                stack.append(char)
            elif char == ']':
                if not stack:
                    return False
                stack.pop()
        return not stack

    return any(is_nested_helper(substring) for substring in string)

