from typing import *
from collections import defaultdict

def factorize(n: int) -> List[int]:
    factors = defaultdict(list)
    i = 2
    while(i * i * i <= n):
        while(n % i == 0:
            factors[i].append((-i, 1))
            n //= i
        i += 1
    if(n > 1):
        factors[n].append((-n, 1))  # Handle n in the list so it comes last
    return factors.values().sort(key=lambda x: -x)

```

