def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Check if the date string is in the correct format
    if not (date[0:2].isdigit() and int(date[0:2]) <= 12 and int(date[2]) <= 31):
        return False

    # Check if the month is valid (1-12)
    if int(date[2]) < 1 or int(date[2]) > 12:
        return False

    # Check if the day is valid (1-31)
    if int(date[1]) < 1 or int(date[1]) > 31:
        return False

    # Check if the year is valid (4 digits)
    if len(date) != 10:
        return False

    # Check if the month is valid (1-12)
    if int(date[0]) < 1 or int(date[0]) > 12:
        return False

    return True
