import collections

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Count the frequency of each letter in the string
    letter_count = collections.Counter(test)

    # Find the letter with the highest frequency and its count
    most_common_letter = letter_count.most_common(1)[0]

    # Return a dictionary containing the letter and its count
    return {most_common_letter[0]: most_common_letter[1]}
