def tribonacci(n):
    arr = [0, 1, 2]
    for i in range(3, n + 1):
        next_val = arr[-1] + arr[-2] + arr[-3]
        arr.append(next_val)
    for i, val in enumerate(arr):
        if arr[i] < 2 or arr[-i - 1] < 0:
            return []
        if i + 1 <= n:
            arr[i] += len(arr) // 2 + arr[-i - 2]
    return arr
