def sum_digits_of_largest_prime(lst: List[int]) -> int:
    """
    Finds the largest prime number in a given list and returns the sum of its digits.

    :param lst: List of integers.
    :return: Sum of the digits of the largest prime number found in the list.
    """
    def is_prime(n):
        """
        Checks if a number is prime.
        :param n: Integer to check.
        :return: True if n is prime, False otherwise.
        """
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_prime = sorted(list(filter(is_prime, lst)))
    return sum(int(digit) for digit in largest_prime)

