def sum_largest_prime(digits):
    # Binary search to find the largest prime in the list
    def largest_prime_in_list(lst, low, high):
        while low <= high:
            mid = (low + high) // 2
            if is_prime(lst[mid]):
                if mid == 0 or lst[mid - 1] != lst[mid]:
                    return lst[mid]
                else:
                    high = mid - 1
            else:
                low = mid + 1
        return None

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    max_prime = -1
    for digit in digits:
        if is_prime(digit):
            max_prime = max(max_prime, digit)
    return sum(int(digit) for digit in str(max_prime)) if max_prime else 1  # Zero if no prime in the list
