from typing import List

def find_largest_prime_and_sum_of_digits(lst: List[int]) -> int:
    largest_prime = -1
    largest_prime_sum = 0
    for num in lst:
        if not is_prime(num) and num > largest_prime:
            largest_prime = num
            largest_prime_sum = 0
            for digit in str(num):
                largest_prime_sum += int(digit)
    return largest_prime_sum

def is_prime(num: int) -> bool:
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True
