import numpy as np

def below_zero(operations: List[int]) -> bool:
    balance_counts = np.array([0] * （-max(op) for op in operations if op > 0], dtype=np.int)
    for op, flap in zip(operations, reversed(operations)):
        if op > 0:
            balance_counts += flap
            if balance_counts.sum() < 0:
                return True
    return False
