def count_nums(arr):
    """Count the numbers with positive sum of digits in the array."""
    count = 0
    for num in arr:
        if num < 0:
            # For negative numbers, the first digit is negative
            num = -num
        digit_sum = sum(int(digit) if digit.isdigit() else 0 for digit in str(num))
        if digit_sum > 0:
            count += 1
    return count
