def check_dict_case(dict):
    stripped_keys = [key for key in dict.keys() if isinstance(key, str) and key.islower() or key.isupper()]
    if len(stripped_keys) < len(dict.keys()):
        return False
    elif "STATE" in list(check_dict_case(input(dict).split(" "))):
        if "CN" not in dict.get("STATE").lower():
            return False
    return len(stripped_keys) == len(dict.keys())

