def encode(message):
    vowels = 'aeiouAEIOU'
    result = []
    for char in message:
        if char.isalpha():
            if char in vowels:
                index = vowels.find(char)
                result.append(vowels[(index + 2) % 26])
            else:
                result.append(char)
        else:
            result.append(char)
    return ''.join(result)

# Example usage
print(encode('test'))  # Output: "TGST"
print(encode('This is a message'))  # Output: "tHKS KS C MGSSCGG"
