import string

def encode(message):
    encoded = ""
    vowels = "aeiouAEIOU"
    for char in message.upper():
        if char in vowels:
            next_char = string.ascii_uppercase[(string.ascii_uppercase.index(char) + 1) % 26]
            encoded += next_char
        else:
            encoded += char
    return encoded
