import functools

def fibfib(n: int) -> int:
    """The FibFib number sequence is a sequence similar to the Fibbonacci sequnece that's defined as follows:
    fibfib(0) == 0
    fibfib(1) == 0
    fibfib(2) == 1
    fibfib(n) == fibfib(n-1) + fibfib(n-2) + fibfib(n-3).
    """
    @functools.lru_cache(maxsize=None)
    def fibfib_helper(i: int) -> int:
        if i == 0 or i == 1 or i == 2:
            return 0
        elif i == 3:
            return 1
        else:
            return fibfib_helper(i - 1) + fibfib_helper(i - 2) + fibfib_helper(i - 3)
    return fibfib_helper(n)


# Check function
def check_function():
    assert fibfib(1) == 0, "The 1st element should be 0"
    assert fibfib(5) == 4, "The 5th element should be 4"
    assert fibfib(8) == 24, "The 8th element should be 24"
    print("All checks passed!")


