import math

def max_fill(grid, capacity):
    m, n = len(grid), len(grid[0])
    buckets = [0] * (n + 1)

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                for k in range(j, n):
                    if grid[i][k] == 0:
                        buckets[k] += capacity
                    else:
                        buckets[k] += 1
                        break

    return sum(buckets)
