import math

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def hex_key(num):
    prime_count = 0
    for digit in str(num):
        if is_prime(int(digit)):
            prime_count += 1
    return prime_count

# Test cases
