def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    closest_vowel = ''

    # Iterate from the end of the word to the beginning
    for i in range(len(word) - 1, -1, -1):
        if word[i] in vowels:
            closest_vowel = word[i]
            break

    # Check if a vowel was found in the middle
    if closest_vowel != '':
        for j in range(len(word) - 1):
            if word[j] in vowels and word[j + 1] in vowels:
                return closest_vowel

    # If no vowel was found, return an empty string
    return closest_vowel
