def sum_squares(lst):
    total_sum = 0
    for index in range(len(lst)):
        # Square the index (for multiples of 3)
        if not index % 3:
            num = index ** 3
        # Cube the index (for multiples of 4, but not for multiples of 3)
        elif not index % 4:
            num = index ** 4
        else:
            num = index
        # Sum the digits in the number
        total_sum += num
    return total_sum
