from collections import deque

def max_fill(grid, capacity):
    import math

    def dfs(x, y, steps, b):
        if not (0 <= x < len(grid) and 0 <= y < len(grid[0])) or grid[x][y] != 1:
            return -1

        steps[x][y] = b
        queue = deque([(x, y)])

        while queue:
            x, y = queue.popleft()
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x + dx, y + dy

                if grid[nx][ny] != 0 and steps[nx][ny] != -1:
                    grid[nx][ny] -= capacity
                    queue.append((nx, ny))

        return steps
