def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    >>> histogram计算的是将字符串中的字母作为一个单词的工具函数
    """
    letters = test.split()
    max_repetition = 0
    letters_info = {}

    for letter in letters:
        if letter in letters_info:
            letters_info[letter] += 1
            if letters_info[letter] > max_repetition:
                max_repetition = letters_info[letter]
            if letters_info[letter] == max_repetition:
                alt = 0
                while letter in letters_info:
                    letters_info[letter] += 1
                    if letters_info[letter] < max_repetition+1:
                        letter_alt = letters_info[letter]
                        letters_info[letter] = letter_alt
                        if letter_alt != max_repetition and letter[0] in alt and letter[0] not in letters_info:
                            alt.append(letter[0])
                        letters_info.pop(letter)
                        break
        else:
            letters_info[letter] = 1

    result = {letter: count for letter, count in letters_info.items()}
    result["others"] = len(result) - len(alt)
    return result
