def monotonic(l: list):
    """Return True if the list is monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if l == []:
        return True
    elif l[0] > l[1]:
        return monotonic(l[1:])
    else:
        return monotonic(l[1:])

