def numerical_letter_grade(grades):
    gpa = grades[0]

    for i in range(1, len(grades)):
        gpa = grades[i] / gpa if i < len(grades) else gpa

    if gpa >= 4.0:
        return [".", "A+", "A-", "B+"]
    elif gpa >= 3.7:
        return ["A"]
    elif gpa >= 3.3:
        return ["A-"]
    elif gpa >= 3.0:
        return ["B+"]
    elif gpa >= 2.7:
        return ["B"]
    elif gpa >= 2.3:
        return ["C+"]
    elif gpa >= 2.0:
        return ["C"]
    elif gpa >= 1.7:
        return ["D+"]
    elif gpa >= 1.3:
        return ["D"]
    elif gpa >= 1.0:
        return ["D-"]
    elif gpa >= 0.7:
        return ["E"]
    else:
        return ["."]

