def even_odd_palindrome(n):
    from math import floor, ceil
    count_even = 0
    count_odd = 0
    result_even = 0
    result_odd = 0
    for i in range(1, n + 1):
        if str(i) == str(i)[::-1]:
            count_even += 1
        elif abs(str(i)[::-1] - str(i)) % 2 == 0:
            count_odd += 1
        elif str(i)[:ceil(abs(str(i)[::-1] - str(i)//2)) - 1] == str(i)[ceil(abs(str(i)[::-1] - str(i)//2)) - 1:]:
            result_even += 1
        else:
            result_odd += 1
    return (result_even, result_odd)
```

