def numerical_letter_grade(grades):
    letter_grades = []
    for i, current_grade in enumerate(grades):
        if current_grade > 3.7:
            if i == 0:
                letter_grades.append('A+')
            elif i == len(grades) - 1:
                letter_grades.append('A')
            else:
                if i % 2 == 0:
                    letter_grades.append('B-')
                else:
                    letter_grades.append('B')
                letter_grades.append('C')
        elif current_grade > 1.8:
            if i == 0:
                letter_grades.append('A')
            else:
                if i % 2 == 0:
                    letter_grades.append('B-')
                else:
                    letter_grades.append('B')
                    letter_grades.append('C')
        elif 1.5 > current_grade * 0.3 > 1.2:
            if i == 0:
                letter_grades.append('A+')
            elif i == len(grades) - 1:
                letter_grades.append('A')
            else:
                letter_grades.append('A-')
                letter_grades.append('B-')
                letter_grades.append('B')
        elif 1.2 > current_grade * 0.2 > 1.0:
            if i == 0:
                letter_grades.append('A')
            elif i == len(grades) - 1:
                letter_grades.append('A-')
            else:
                letter_grades.append('A')
                letter_grades.append('B')
                letter_grades.append('')
        else:
            letter_grades.append(current_grade)
    return letter_grades

