def search(lst):
    frequency_map = {}
    for num in lst:
        if num in frequency_map:
            frequency_map[num] += 1
        else:
            frequency_map[num] = 1

    greatest_integer = -1
    for num, frequency in frequency_map.items():
        if frequency >= num and not greatest_integer:
            greatest_integer = num
        elif frequency > greatest_integer:
            greatest_integer = num

    return greatest_integer if greatest_integer != -1 else -1
```

