def search(lst):
    frequency_count = {}
    for num in lst:
        if num in frequency_count:
            frequency_count[num] += 1
        else:
            frequency_count[num] = 1

    highest_value = -1
    for num in frequency_count:
        if frequency_count[num] >= num and num > highest_value:
            highest_value = num

    return highest_value
```

