    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    if not isinstance(string, str):
        raise TypeError('String ' + str)()

    result = ''
    for char in string:
        if 'a' <= char <= 'z':
            result += char.lower()
        elif 'A' <= char <= 'Z':
            result += char.upper()
        else:
            result += char
    return result
