def is_nested(string):
    stack = []
    for c in string:
        if c == '[':
            stack.append(c)
        elif c == ']' and stack and stack[-1] == '[':
            stack.pop()
        elif c == ']' and not stack:
            return False
    return not stack and len(stack) == 0

