def is_nested(string):
    def is_nested_bracket(string, i, d orig_len):
        if orig_len == 2:
            # Check if the current position represents a single nested
            # brackets character
            if string[i] == '(' or string[i] == '[' or string[i] == '{':
                return False
            elif i + d - 1 < len(string) and string[i + d - 1] == ')':
                return False
            else:
                return False
        # For other brackets, check the distance to the end of the string
        elif string[i:i+d] == string[i+1:i+d+1] or string[i:i+d+2] == string[i+1:i+d+2]:
            return True
    return any(is_nested_bracket(string, i, d) for d in range(len(string) + 1))
