def max_fill(grid, capacity):
    # Calculate the number of filled wells
    filled_wells = sum(grid[i][0] for i in range(len(grid)))
    # Fill the wells with the given capacity
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                grid[i][j] = capacity
    # Count the number of times the last filled well needs a bucket
    return filled_wells - sum(grid[i][1] for i in range(len(grid)) if grid[i][1] > 0)
