def max_fill(grid, capacity):
    import math

    # Calculate the number of wells that can be filled using a bucket with the given capacity
    fill_wells = sum(1 for well in grid if well[0] == 1 and well[1] <= capacity)

    # Calculate the number of additional wells that need to be filled
    additional_wells = 0
    for well in grid:
        if well[0] == 1:
            if well[1] > capacity:
                additional_wells += 1
            else:
                additional_wells += capacity - well[1]

    # Return the total number of wells that can be filled and the additional wells that need to be filled
    return fill_wells + additional_wells
