def vowels_count(s):
    vowels = ['a', 'e', 'i', 'o', 'u', 'y']
    vowels_count = 0
    vowels_index = [1, 1, 1, 1, 1, 0]  # Assuming 'y' is synonymous with 'yin' or 'yi'. Numbers correspond to the number of vowel characters: 0 - 'i', 1 - 'e', 2 - 'a', 3 - 'o', 4 - 'u'

    for index, char in enumerate(s):
        if char in vowels:
            if index < len(s) - 1 and vowels_index[index + 1] >= len(s) // 4 and vowels_index[index + 1] != len(s) and vowels_index[index + 1] < vowels_index[index]:
                vowel_index = index + 1
            else:
                return vowels_count  # Return 0 if set doesn't fit

            if 'y' in vowels[char] and char not in ('a', 'e', 'i', 'o', 'u'):
                vowels_index[vowel_index] += 1
            elif 'y' in vowels and char in ('a', 'e', 'i', 'o', 'u'):
                vowels_index[vowel_index] += 2

    vowels_count = sum(vowels_index)
    return vowels_count

# Example usage:
print(vowels_count("abcde"))  # Output: 2
print(vowels_count("ACEDY"))  # Output: 3
