import math

def fib(n: int) -> int:
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    if n == 0 or n == 1:
        return n
    elif n % 2 == 0:
        return fib(n - 1) + fib(n - 2)
    else:
        return fib(n - 2) + fib(n - 1)
