def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 2
    elif n == 2:
        return 3
    elif n == 3:
        return 5
    elif n == 4:
        return 13
    elif n == 5:
        return 89
    else:
        fib_num = 2
        count = 0
        while count < n - 2:
            if is_prime(fib_num):
                count += 1
                if count == n - 2:
                    return fib_num
            fib_num += 1
        return "The number you entered is not prime."

def is_prime(num: int) -> bool:
    """Returns True if the given number is prime, else False."""
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

