from typing import List

def is_happy(s: str) -> bool:
    """Check if the string is happy."""
    if len(s) < 3:
        return False
    seen = set()
    for i in range(len(s) - 2):
        if s[i] in seen or s[i:i+3] not in seen:
            return False
        seen.add(s[i:i+3])
    return True
