def sum_product(numbers: t.List[int]) -> t.Tuple[int, int]:
    if not numbers:
        return 0, 1
    else:
        sum_of_numbers = sum(numbers)
        product_of_numbers = 1
        for num in numbers:
            product_of_numbers *= num
        return sum_of_numbers, product_of_numbers
