def will_it_fly(q, w):
    # Check if the object q is balanced
    if not q:
        return False
    # Check if the sum of the elements in q is less than or equal to w
    if sum(q) > w:
        return False
    # Check if q is a palindrome
    if q != q[::-1]:
        return False
    return True
