from typing import List

def max_fill(grid: List[List[int]], capacity: int) -> int:
    import math
    rows, cols = len(grid), len(grid[0])
    left, right = 0, rows - 1
    max_fill = 0

    while left <= right:
        mid = (left + right) // 2
        water = 0

        for i in range(rows):
            if grid[i][mid] == 1:
                water += 1
                if mid > 0:
                    water += grid[i][mid - 1] == 1
                if mid < rows - 1:
                    water += grid[i][mid + 1] == 1

        if water <= capacity:
            left = mid + 1
            max_fill = max(max_fill, mid)
        else:
            right = mid - 1

    return max_fill
