import numpy as np

def double_the_difference(lst):
    if not lst:
        return 0

    even_sum = 0
    odd_sum = 0
    original_lst = lst.copy()
    is_negative = False
    for number in lst:
        if number < 0:
            is_negative = True
        if number % 2 != 0 and not is_negative:
            odd_sum += number ** 2

            if original_lst.index(number) < len(original_lst) // 2:
                even_sum += number ** 2

    if is_negative:
        even_sum = -even_sum

    return even_sum + odd_sum

