import unittest

def will_it_fly(q, w):
    return q == q[::-1] and sum(q) <= w

class TestWillItFly(unittest.TestCase):
    def test_balanced_and_balanced(self):
        self.assertTrue(will_it_fly([1, 2], 5))
        self.assertTrue(will_it_fly([3, 2, 3], 1))
        self.assertTrue(will_it_fly([3, 2, 3], 9))
        self.assertTrue(will_it_fly([3], 5))

    def test_unbalanced(self):
        self.assertFalse(will_it_fly([3], 5))

    def test_empty_list(self):
        self.assertFalse(will_it_fly([], 5))

    def test_balanced_and_overweight(self):
        self.assertTrue(will_it_fly([3], 10))

    def test_balanced_and_equal(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_unbalanced_or_overweight(self):
        self.assertFalse(will_it_fly([3, 2, 3], 9) | will_it_fly([3], 10))

unittest.main()

