import re

def split_words(txt):
    # Split the text on whitespace if no whitespaces exist
    if re.match(r'\s+', txt):
        return txt.split()
    # Split the text on commas if no commas exist
    elif re.match(r',+', txt):
        return txt.split(',')
    else:
        # If no whitespace or commas are found, count the number of lower-case letters with odd order in the alphabet
        return sum(ord(char) - ord('a') + 1 for char in txt if char.islower() and ord(char) - ord('a') % 2 == 1)
