def is_simple_power(x, n):
    """Check if x is a simple power of n."""
    if x == 1:
        return True
    if n <= 1:
        return False
    if n == 2:
        return n == 2 and x == 1
    if n % 2 == 0:
        return False
    for i in range(3, int(x ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True


