def additionalFilter(nums):
    if not nums:
        return 0
    count = 0
    for num in nums:
        count += all(
            num1 % 2 != 0 and num1 % 10 % 2 != 0 and num2 % 2 != 0 and num2 % 10 % 2 != 0 and num1 != 0 and num1 != 10 and num2 != 0
        for num1 in num
        for num2 in str(abs(num))
    )
    return count

def specialFilter(nums):
    # Ensure nums is a list to avoid KeyError
    return additionalFilter(sorted(nums, reverse=True))

```

