def specialFilter(nums):
    def is_first_or_last_digit_odd(num):
        return isinstance(num, int) and str(num).startswith('1', 0) or str(num).endswith('1', 0)

    odd_dnumbers = [num for num in nums if is_first_or_last_digit_odd(num) and int(str(num)[::1]) % 2 != 0]

    return len(odd_dnumbers)

# Example usage
