    elif not negative_integers and positive_integers:
        return negative_integers[num_zeros % 2], positive_integers[num_ones % 2]
    elif positive_integers and not negative_integers:
        return positive_integers[num_zeros % 2], None
    else:
        return negative_integers[num_zeros % 2], positive_integers[num_ones % 2]

