def closest_integer(value):
    '''
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15

    Note:
    Rounding away from zero means that if the given number is equidistant
    from two integers, the one you should return is the one that is the
    farthest from zero. For example closest_integer("14.5") should
    return 15 and closest_integer("-14.5") should return -15.
    '''
    # Check if the input is already an integer or a float
    if value.replace('.', '', 1).isdigit():
        return int(value)
    else:
        # Split the string into two numbers
        parts = value.split('.')
        # Determine the closer integer based on the number of decimal places
        if len(parts) == 1:
            return max(int(parts[0]), 10**len(parts[0]) - 1)
        elif len(parts) == 2:
            # If there are two numbers, round away from zero
            return int(parts[1]) + abs(int(parts[0]) - 10**len(parts[0]) / 10)
        else:
            # If there are three or more numbers, return the smaller of the two
            return min(int(parts[0]) + abs(int(parts[1]) - 10**len(parts[0]) / 10), int(parts[1]) + abs(int(parts[0]) - 10**len(parts[0]) / 10))
