def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    if a < 3:
        return False

    for i in range(2, int(a**0.5) + 1):
        if a % i == 0:
            return False

    return is_prime(a) and is_prime(a // 3) and is_prime(a // 9) and is_prime(a // 27) and is_prime(a // 81)

# Test cases
print(is_multiply_prime(30))  # Expected output: True
print(is_multiply_prime(49))  # Expected output: False
print(is_multiply_prime(100))  # Expected output: True
