def tri(n):
    """Return the first n + 1 numbers of the Tribonacci sequence."""
    if n == 0:
        return [0]
    elif n == 1:
        return [3]
    elif n == 2:
        return [1, 3, 2]

    tribos = [0, 3, 2]
    for i in range(3, n + 1):
        tribos.append(tribos[-1] + tribos[-2] + tribos[-3])

    return tribos
```

```python
def tri(n):
    if n == 1:
        return [1]
    elif n == 2:
        return [1, 3]
    else:
        trib = [1, 3]
        for i in range(2, n):
            if i % 2 == 0:
                trib.append(trib[i-1] + trib[i-2])
            else:
                trib.append(trib[i-1] + trib[i-2] + trib[i+1])
        return trib[:n+1]

# Example usage:
print(tri(3))  # Output: [1, 3, 2, 8]
```

```python
def tribonacci(n):
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]
    elif n == 3:
        return [1, 3, 2]

    tribonacci_list = [1, 3]
    for i in range(2, n):
        next_value = tribonacci_list[-1] + tribonacci_list[-2] + tribonacci_list[-3]
        tribonacci_list.append(next_value)

    return tribonacci_list
```

