import datetime

def valid_date(date):
    try:
        # Convert the date string to a datetime object and check if it's None
        if datetime.datetime.strptime(date, '%m-%d-%Y') is None:
            return False

        # Check if the date is valid
        if 1 <= int(date[:2]) <= 12:
            if int(date[2:]) >= 1 and int(date[2:]) <= 30:
                if int(date[2:]) % 4 == 0 and int(date[2:]) % 100 != 0 or int(date[2:]) % 400 == 0:
                    return True
                else:
                    return False
            else:
                return False
        else:
            return False
    except ValueError:
        return False
