def numerical_letter_grade(grades):
    letter_grades = []
    for gpa in grades:
        if 4.0 <= gpa <= 3.7:
            letter_grades.append('A+')
        elif 3.7 < gpa <= 3.3:
            letter_grades.append('A')
        elif 3.3 < gpa <= 2.7:
            letter_grades.append('A-')
        elif 2.7 < gpa <= 2.3:
            letter_grades.append('B+')
        elif 2.3 < gpa <= 2.0:
            letter_grades.append('B')
        elif 2.0 < gpa <= 1.7:
            letter_grades.append('B-')
        elif 1.7 < gpa <= 1.3:
            letter_grades.append('C+')
        elif 1.3 < gpa <= 1.0:
            letter_grades.append('C')
        elif 1.0 < gpa <= 0.7:
            letter_grades.append('C-')
        elif gpa <= 0.0:
            letter_grades.append('D+')
        elif gpa <= 1.0:
            letter_grades.append('D')
        elif gpa <= 1.0:
            letter_grades.append('E')
    return letter_grades
