def exchange(lst1, lst2):
    if not lst1 or not lst2 or len(lst1) != len(lst2):
        return "NO"

    odd_count = 0
    for num in lst1:
        if num % 2 != 0:
            odd_count += 1

    if odd_count > 0:
        return "NO"

    for num in lst2:
        if num % 2 == 0:
            lst1 += [num]
            break

    return "YES"
