def match_parens(lst):
    # Helper function to check if a string of parentheses is balanced
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Check if any of the two strings is a balanced string
    if not is_balanced(lst[0]) or not is_balanced(lst[1]):
        return 'No'

    # Case: If both strings are balanced, concatenate them and check if the resulting string is balanced
    auxiliary_lst = lst[0] + lst[1]
    if not is_balanced(auxiliary_lst):
        return 'No'

    return 'Yes'
```

