import string

def encrypt(s):
    alphabet = string.ascii_lowercase

    for i in range(len(s)):
        if s[i] in alphabet:
            alphabet = adjacent_chars(alphabet, s[i])
    return ''.join(alphabet)

def adjacent_chars(s1, char):
    if len(s1) < 2:
        return s1
    mid = (len(s1) - 1) // 2
    left, right = '', ""
    for i in range(2):
        if i < 1:
            left = right = s1[mid][char + i]
        else:
            right = s1[mid - 2][char + i]
        if mid - 2 >= 0:
            right += s1[mid - 2][char]
        else:
            pass
    return left + char + ': ' + right

