import sys

def is_sorted(arr):
    """Check if the array 'arr' is sorted in non-decreasing order."""
    return all(a <= b for a, b in zip(arr, arr[1:]))

def move_one_ball(arr):
    """Check if it is possible to obtain a sorted array by performing right
    shift operations on the given array."""
    return is_sorted(arr) and not is_sorted(arr[1:] + [sys.maxsize])

