def get_max_triples(n):
    from functools import reduce

    def add_mod3(x):
        return (x + 1) % 3

    def get_product_of_three(x):
        return reduce(add_mod3, x)

    max_triples = 0
    for i in range(1, n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if get_product_of_three([i, j, k]) % 3 == 0:
                    max_triples += 1
    return max_triples
```

