def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    closest_vowel = ""

    for i in range(len(word)):
        if word[i] in vowels:
            if i > 0 and word[i-1] not in vowels and i < len(word) - 1 and word[i+1] not in vowels:
                closest_vowel = word[i]
                break

    return closest_vowel
```

