import collections

def search(lst):
    frequency = collections.Counter(lst)
    max-frequency = -1
    index = -1

    for i, (num, freq) in enumerate(frequency.items()):
        if freq >= num:
            index = i

    return max(index, 0)
```

The complete function `search` takes a list `lst` of positive integers and returns the greatest integer greater than zero with a priority frequency larger than or equal to its value rather than its index.

```python
def search(lst):
    frequency = {}

    # Count the frequency of each element in the list
    for num in lst:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_value = -1
    for num in lst:
        if max_value == 0:
            if frequency[num] < num:
                # If the current value equals 0 with lesser frequency, stop to find the largest generated greater number
                break
            max_value = num

    return max_value

# Example usage
print(search([4, 1, 2, 2, 3, 1]))  # Output: 2
print(search([1, 2, 2, 3, 3, 3, 4, 4, 4]))  # Output: 3
print(search([5, 5, 4, 4, 4]))  # Output: -1
```

```python

def search(lst):
    '''
    Return the greatest integer that is greater than zero and has a frequency greater than or equal to the value of the integer itself.
    If no such a value exist, return -1.
    '''
    frequency = {}
    for num in lst:
        frequency[num] = frequency.get(num, 0) + 1

    greatest_value = -1
    for num, freq in frequency.items():
        if freq >= num and num > greatest_value:
            greatest_value = num

    return greatest_value if greatest_value != -1 else -1
```

