def get_closest_vowel(word):
    vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']
    closest_vowel = ''
    for i in range(1, len(word)):
        if word[i] not in vowels:
            break
        if word[i - 1] in vowels[:i - 1] and word[i + 1] not in vowels[i + 1:]:
            closest_vowel = word[i] if len(closest_vowel) > len(word[i]) else closest_vowel
    return closest_vowel
```

