    def get_closest_vowel(word):
        vowels = 'aeiouAEIOU'
        vowel_indices = []

        # Find indices of vowels and consonants
        for i, char in enumerate(word):
            if char in vowels:
                if not vowel_indices or len(vowel_indices) > 1:
                    vowel_indices.append((i, char))
                elif i < len(word) - 1 and word[i + 1] not in vowels:
                    vowel_indices.pop()

        # Find the closest vowel according to condition
        closest_vowel = word[0]
        for vowel_index, char in vowel_indices:
            if abs(vowel_index[0] - vowel_index[1]) <= 1:
                closest_vowel = char

        return closest_vowel

