from datetime import datetime

def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Parse the date string into a datetime object
    try:
        datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    # Check if the date is valid
    if datetime.strptime(date, '%m-%d-%Y')..month < 1 or datetime.strptime(date, '%m-%d-%Y').month > 12:
        return False
    if datetime.strptime(date, '%m-%d-%Y').day < 1 or datetime.strptime(date, '%m-%d-%Y').day > 31:
        return False
    if datetime.strptime(date, '%m-%d-%Y').month in [4, 6, 9, 11] and datetime.strptime(date, '%m-%d-%Y').day < 1 or datetime.strptime(date, '%m-%d-%Y').day > 29:
        return False
    if datetime.strptime(date, '%m-%d-%Y').month in [1, 3, 5, 7, 8, 10, 12] and datetime.strptime(date, '%m-%d-%Y').day < 1 or datetime.strptime(date, '%m-%d-%Y').day > 30:
        return False

    return True
```

This Python function `valid_date` checks a given date string to ensure it is valid according to the specified rules. It uses the `datetime` module to parse the date string into a `datetime` object and perform validation based on the month, day, and year. If all checks pass, the function returns `True`, otherwise it returns `False`.

