def valid_date(date):
    # Check if the date string is not empty
    if not isinstance(date, str) or len(date) != 5:
        return False

    # Check the number of days for each month
    if len(date.split("-")) != 3:
        return False

    month, day, year = map(int, date.split("-"))

    # Validate the month
    if month < 1 or month > 12:
        return False

    # Validate the day
    if day < 1 or day > 30:
        return False

    # Validate the year
    if year < 2000:
        return False
    if year % 4 == 0 and year % 100 != 0 or year % 400 == 0:
        return False
    return True
