def largest_smallest_integers(lst):
    # Identify negative integers
    negative_integers = [num for num in lst if num < 0]
    # Raise an unxecutable exception if zero or more are found
    if len(negative_integers) > 0:
        return None, max(negative_integers)
    # Identify positive integers
    positive_integers = [num for num in lst if num >= 0]
    # If no positive or negative integers are found, return None
    if len(positive_integers) == 0:
        return None, None
    # Return the largest and smallest values
    return max(positive_integers), min(positive_integers, default=0)
```

