from typing import Tuple

def bf(planet1: str, planet2: str) -> Tuple[str, ...]:
    # Check if both planet1 and planet2 are valid planet names
    if not isinstance(planet1, str) or not isinstance(planet2, str):
        return ()

    # Filter and sort the planets based on their proximity to the sun
    filtered planets = sorted(list(set(planet1.lower() + planet2.lower()).difference({"Earth", "Mars", "Jupiter", "Saturn", "Uranus"})))

    # Return a tuple of all planets within the specified range
    return tuple(planet for planet in filtered if planet in ("Mercury", "Venus", "Earth", "Mars", "Jupiter", " saturn", "Uranus"))
