def search(lst):
    '''
    Complete the function
    '''
    from collections import Counter
    freq = Counter(lst)
    freq = {k: v for k, v in freq.items() if v >= k}
    if not freq:
        return -1
    return max(freq, key=lambda k: (-freq[k], k))
