    while n != 1:
        if n % 2 == 0:
            n = n // 2  # If divisible by 2, reduce by half
        else:
            n = 3 * n + 1  # If odd, multiply by 3 and add 1
        odd_collatz_sequence.append(n)  # Append the next odd number to the sequence

