from typing import List

def do_algebra(operator: List[str], operand: List[int]) -> int:
    """
    Given two lists operator, and operand, the function first parses the operator name and operand to
    perform algebraic operations. It then constructs the algebraic expression using the parsed operator names
    and operands. Finally, it evaluates the constructed algebraic expression and returns the result.
    """
    result = 0
    parts = list(zip(operator, operand))

    for part in parts:
        if part[0] == '+':
            result += part[1]
        elif part[0] == '-':
            result -= part[1]
        elif part[0] == '*':
            result *= part[1]
        elif part[0] == '//':
            result //= part[1]
        elif part[0] == '**':
            result **= part[1]

    return result
