def simplify(x, n):
    try:
        # Convert the string representations of the fraction into floating-point numbers
        num1, denom1 = float(x), float(n)
        # Simplify the fraction
        num2 = int(num1) // int(denom1)
        # Compare the simplified fraction with the original one
        return int(num2) == int(x * n)
    except ValueError:
        # If division by zero is detected, return False
        return False
