def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    count = 0
    num = 2  # Starting with the first two Fibonacci numbers
    while True:
        if is_prime(num) and num % 2 != 0 and num > 1:
            count += 1
            if count == n:
                return num
        num += 1

def is_prime(num: int) -> bool:
    """
    is_prime returns True if the given number is a prime number, False otherwise.
    """
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True
```

