from typing import List


def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0

    mean = sum(numbers) / len(numbers)
    try:
        range_of_deviations = sum((x - mean) ** 2 for x in numbers)
        mad = range_of_deviations / len(numbers)
        return mad
    except ZeroDivisionError:
        return "Possible error in calculation."
