import sys

def fibfib(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    elif n == 3:
        return 1
    else:
        ans = fibfib(n-1)
        if n % 3 == 0:
            ans += fibfib(n-2)
        elif n % 3 == 1:
            ans += fibfib(n-3)
        elif n % 3 == 2:
            return fibfib(n - 1)
        return ans
```

