import math

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers less than n."""
    primes = []
    count = 0
    num = 2
    while count < n:
        if is_prime(num):
            primes.append(num)
            count += 1
        num += 1
    return primes
```

