def file_name_check(file_name):
    if len(file_name) > 3:
        return 'No'
    if file_name.startswith('0123456789'):
        return 'No'
    if file_name[1:] != '':
        return 'No'
    if file_name[1:] in ['txt', 'exe', 'dll']:
        return 'Yes'
    return 'No'
