def reverse_delete(s, c):
    # Create a set from character c to find matching characters
    matching_chars = set(c)

    # Reverse the string s and add all characters to the set
    reversed_s = s[::-1]
    for char in reversed_s:
        if char in matching_chars:
            matching_chars.remove(char)

    # Check if the result string is a palindrome
    result = ''.join(reversed_s)
    return (result, len(result) > 0 and result == result[::-1])
```

