def reverse_delete(s, c):
    # Initialize a list to store the result
    result = []

    # Iterate through the string s
    for char in s:
        # Check if the character is in c
        if char in c:
            # If it is, add it to the result list
            result.append(char)

    # Reverse the result list
    result.reverse()

    # Check if the result list is a palindrome
    if result == result[::-1]:
        # Return the result string and True
        return (''.join(result), True)
    else:
        # Return the result string and False
        return (''.join(result), False)
