def closest_integer_value(numbers):
    def closest_distance(val=None):
        if val is None:
            val = float(numbers)

        dist_from_zero = abs(val) // 1
        value_as_string = str(val)
        if value_as_string[0] == '-':
            if dist_from_zero > 0:
                return f"{dist_from_zero - 1}"
            else:
                return f"{int(value_as_string) + 1}"
        else:
            if dist_from_zero == 1:
                return f"{val}"
        return ""

    return closest_distance()

# Example usage:
# print(closest_integer_value("10")) # output: 10
# print(closest_integer_value("15.3")) # output: 15
