def split_words(txt):
    # Check for whitespace
    if ' ' in txt or '\n' in txt or '\t' in txt:
        return txt.split()
    else:
        # Count lowercase letters with odd order in the alphabet
        odd_order_count = sum(1 for char in txt if ord(char) >= ord('a') and ord(char) <= ord('z') and ord(char) % 2 == 1)
        return odd_order_count
```

