from functools import lru_cache

def fibfib(n: int) -> int:
    @lru_cache(maxsize=None)
    def helper(x):
        if x <= 1:
            return x
        return fibfib(x - 1) + fibfib(x - 2) + fibfib(x - 3)
    return helper(n)
```

