from math import reduce

def simplify(x, n):
    # Double-check for integer division
    if int(1 * x) / (int(n[1]) + 1) == reduce(lambda a, b: int(a) / int(b), [int(e) for e in x] + [int(n[1])], 1):
        return True
    else:
        return False
```

