def triangle_area(a, b, c):
    # Check if the given sides form a valid triangle
    if a + b > c and a + c > b and b + c > a:
        # Calculate and return the area using Heron's formula
        area = (a * (a + b + c) - (a + b) * (a + b)) ** 0.5
        return round(area, 2)
    else:
        return -1
