from typing import List

def skjkasdkd(lst):
    from math import sqrt

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def digit_sum(n: int) -> int:
        return sum(map(int, str(n)))

    sum_of_digits = 0
    for num in lst:
        if is_prime(num):
            sum_of_digits += digit_sum(num)
    return sum_of_digits
