import collections

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Count the frequency of each character in the test string
    char_count = collections.Counter(test)

    # Find the character(s) with the maximum frequency
    most_common_chars = char_count.most_common()

    # Return a dictionary containing the character(s) and their frequency
    return dict(most_common_chars)

