    test_cases = [
        ("Hello world", "3e25960a79dbc69b674cd4ec67a72c62"),
        ("", None),
        ("abc", "a593b1ce3saf"),
    ]

    for text, expected in test_cases:
        assert string_to_md5(text) == expected, f"Failed on {text}"
    print("All test cases passed!")


