import sys

def words_in_sentence(sentence):
    words = []
    for word in sentence.split(' '):
        if len(word) > 1:
            arr = str(word).split(',')
            arr.sort(reverse=True)
            for i in range(len(arr)):
                arr[i] = int(arr[i])
            for i in range(len(arr)):
                if arr[i] == max(arr):
                    if i == 0:
                        words.append(word)
                    else:
                        words[-1] = word
    return ' '.join(words)

# Example usage
if __name__ == "__main__":
    sentence = sys.stdin.read().strip()
    print(words_in_sentence(sentence))

