from collections import deque

def separate_paren_groups(paren_string: str) -> List[str]:
    separate_list = []
    stack = deque()
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) > 0:
                stack.pop()
            else:
                # Maintain balance by adding '()' at the end of the string
                separate_list.append('()')
    return separate_list
