def prime_length(s):
    """Check if the length of the string is a prime number"""
    # Count the length of the string
    length = len(s)

    # Check if the length is a prime number
    if length % 2 == 0 or length < 2:
        return False
    else:
        # Check divisibility by numbers up to the square root of the length
        for i in range(3, int(length**0.5) + 1, 2):
            if length % i == 0:
                return False
        return True
