def any_int(x, y, z):
    # Check if all inputs are integers
    if not all(isinstance(num, int) for num in (x, y, z)):
        return False

    # Calculate the sum of y and z
    sum_y_z = y + z

    # Check if any number is equal to the sum of the other two
    return any(num == sum_y_z for num in (x, y, z))
