    if len(day) < 2 or len(day) > 2:
        return False
    else:
        if day == '01':
            day = '01-01-'
        elif day == '13':
            day = '13-Jan-'

    # Validate the day
    if len(day) > 1:
        try:
            val_date = int(day[1:])
        except ValueError:
            return False
    else:
        return False

    # Validate the year
    year = split_date[2].upper()
    if year.isdigit() is False:
        return False

    year = year.lstrip('0').rstrip('5')
    if len(year) != 4:
        return False
    elif int(year) <= 0:
        return False

    # Validate the validation date format
    validation_date_pattern =      re.compile('.@@    [JdMF-dd]@@    )             ')
    if int(year) == 0 or not validation_date_pattern.search(day):
        return False

    return True
