    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    return tuple(planets[i] for i in range(len(planets) if planet1 in planets else len(planets) - 1) if planet2 in planets[i + 1:])

